--- a/src/amr_utils/include/amr_utils/odom_math.hpp
+++ b/src/amr_utils/include/amr_utils/odom_math.hpp
@@ -14,4 +14,7 @@
 // Dead reckoning for a differential-drive base: linear speed v (m/s), angular speed w (rad/s), time step dt (s).
 Pose2D integrate_diff_drive(const Pose2D& pose, double v, double w, double dt);

+// Compose two poses: b is relative to a.
+Pose2D compose(const Pose2D& a, const Pose2D& b);
+
 }  // namespace amr_utils

--- a/src/amr_utils/src/odom_math.cpp
+++ b/src/amr_utils/src/odom_math.cpp
@@ -18,4 +18,12 @@
   return out;
 }

+Pose2D compose(const Pose2D& a, const Pose2D& b) {
+  Pose2D out;
+  out.x = a.x + std::cos(a.theta) * b.x - std::sin(a.theta) * b.y;
+  out.y = a.y + std::sin(a.theta) * b.x + std::cos(a.theta) * b.y;
+  out.theta = normalize_angle(a.theta + b.theta);
+  return out;
+}
+
 }  // namespace amr_utils

--- a/src/amr_utils/test/test_odom_math.cpp
+++ b/src/amr_utils/test/test_odom_math.cpp
@@ -28,3 +28,33 @@
   EXPECT_NEAR(p.y, 2.0, 1e-9);
   EXPECT_NEAR(p.theta, 0.5, 1e-9);
 }
+
+TEST(Compose, ComposeIdentity) {
+  Pose2D a = {1.0, 2.0, 0.5};
+  Pose2D b = {0.0, 0.0, 0.0};
+  Pose2D res = amr_utils::compose(a, b);
+  EXPECT_NEAR(res.x, 1.0, 1e-9);
+  EXPECT_NEAR(res.y, 2.0, 1e-9);
+  EXPECT_NEAR(res.theta, 0.5, 1e-9);
+}
+
+TEST(Compose, ComposeWithRotation) {
+  // a is rotated 90 degrees (PI/2)
+  Pose2D a = {1.0, 1.0, M_PI / 2.0};
+  // b is moving 1.0 unit forward in a's frame (which is world's y direction)
+  Pose2D b = {1.0, 0.0, 0.0};
+  Pose2D res = amr_utils::compose(a, b);
+  // Expected: x = 1 + cos(pi/2)*1 - sin(pi/2)*0 = 1
+  //           y = 1 + sin(pi/2)*1 + cos(pi/2)*0 = 2
+  //           theta = pi/2
+  EXPECT_NEAR(res.x, 1.0, 1e-9);
+  EXPECT_NEAR(res.y, 2.0, 1e-9);
+  EXPECT_NEAR(res.theta, M_PI / 2.0, 1e-9);
+}
+
+TEST(Compose, ComposeAngleWrap) {
+  Pose2D a = {0.0, 0.0, M_PI * 0.8};
+  Pose2D b = {0.0, 0.0, M_PI * 0.4}; // Total 1.2 PI, should wrap to -0.8 PI
+  Pose2D res = amr_utils::compose(a, b);
+  EXPECT_NEAR(res.theta, -0.8 * M_PI, 1e-9);
+}

